class Solution {
public:
    bool containsNearbyAlmostDuplicate(vector<int>& nums, int indexDiff, int valueDiff) {
        if (valueDiff < 0) return false;
        long long w = (long long)valueDiff + 1;
        unordered_map<long long, long long> buckets;
        auto getBucket = [&](long long x) {
            return x >= 0 ? x / w : ((x + 1) / w) - 1;
        };
        for (int i = 0; i < (int)nums.size(); i++) {
            long long x = nums[i];
            long long m = getBucket(x);
            if (buckets.count(m)) return true;
            if (buckets.count(m - 1) && abs(x - buckets[m - 1]) <= valueDiff) return true;
            if (buckets.count(m + 1) && abs(x - buckets[m + 1]) <= valueDiff) return true;
            buckets[m] = x;
            if (i >= indexDiff) {
                buckets.erase(getBucket(nums[i - indexDiff]));
            }
        }
        return false;
    }
};

class Solution {
    public boolean containsNearbyAlmostDuplicate(int[] nums, int indexDiff, int valueDiff) {
        if (valueDiff < 0) return false;
        long w = (long) valueDiff + 1;
        Map<Long, Long> buckets = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            long x = nums[i];
            long m = x >= 0 ? x / w : ((x + 1) / w) - 1;
            if (buckets.containsKey(m)) return true;
            if (buckets.containsKey(m - 1) && Math.abs(x - buckets.get(m - 1)) <= valueDiff) return true;
            if (buckets.containsKey(m + 1) && Math.abs(x - buckets.get(m + 1)) <= valueDiff) return true;
            buckets.put(m, x);
            if (i >= indexDiff) {
                long old = nums[i - indexDiff];
                long oldBucket = old >= 0 ? old / w : ((old + 1) / w) - 1;
                buckets.remove(oldBucket);
            }
        }
        return false;
    }
}

