var containsNearbyAlmostDuplicate = function(nums, indexDiff, valueDiff) {
    if (valueDiff < 0) return false;
    const w = valueDiff + 1;
    const buckets = new Map();
    const getBucket = (x) => Math.floor(x / w);
    for (let i = 0; i < nums.length; i++) {
        const x = nums[i];
        const m = getBucket(x);
        if (buckets.has(m)) return true;
        if (buckets.has(m - 1) && Math.abs(x - buckets.get(m - 1)) <= valueDiff) return true;
        if (buckets.has(m + 1) && Math.abs(x - buckets.get(m + 1)) <= valueDiff) return true;
        buckets.set(m, x);
        if (i >= indexDiff) {
            buckets.delete(getBucket(nums[i - indexDiff]));
        }
    }
    return false;
};
